package com.payroll.repository; import com.payroll.model.Employee; import org.springframework.data.jpa.repository.JpaRepository; import java.util.*; public interface EmployeeRepository extends JpaRepository<Employee,Long>{ Optional<Employee> findByEmployeeCode(String code); List<Employee> findByFullNameContainingIgnoreCaseOrEmployeeCodeContainingIgnoreCase(String name,String code); long countByDepartment(String department); }